def all_prompts():
    """Flache Liste (nr, kategorie, titel, prompt)."""
    out = []
    n = 0
    for cat, _desc, items in CATEGORIES:
        for title, prompt in items:
            n += 1
            out.append((n, cat, title, prompt))
    return out


if __name__ == "__main__":
    ps = all_prompts()
    print(len(ps), "Prompts")
    for cat, _d, items in CATEGORIES:
        print(f"  {cat}: {len(items)}")
